import billing, gateway, plans
class Fake:
    def __init__(self, script=()):
        self.script, self.charges, self.keys, self.calls, self.arguments = list(script), [], {}, 0, []
    def create_charge(self, order_id, amount_cents, description='', idempotency_key=None):
        self.calls += 1
        self.arguments.append([order_id, amount_cents, description])
        step = self.script.pop(0) if self.script else 'ok'
        if isinstance(step, Exception):
            raise step
        if step == 'lost':
            raise gateway.GatewayTimeout('before')
        if idempotency_key is not None and idempotency_key in self.keys:
            charge_id = self.keys[idempotency_key]
        else:
            charge_id = 'ch_%d' % (len(self.charges) + 1)
            self.charges.append([order_id, amount_cents, description])
            if idempotency_key is not None:
                self.keys[idempotency_key] = charge_id
        if step == 'late':
            raise gateway.GatewayTimeout('after')
        return charge_id
def order(order_id, *payments):
    return {'id':order_id, 'payments':[{'id':i, 'amount_cents':a, 'purpose':p, 'status':'due'} for i,a,p in payments]}
def seen(order):
    return [[p['status'],p.get('charge_id')] for p in order['payments']]
g = Fake(['late','ok','lost','lost','ok'])
o = plans.collect(g, order('oak', ('a',700,'installment'), ('b',700,'installment')))
result = [seen(o),g.calls,len(g.charges)]

